BEGIN TRANSACTION;
CREATE TABLE "Sectors" (
    "Id" TEXT NOT NULL CONSTRAINT "PK_Sectors" PRIMARY KEY,
    "Name" TEXT NOT NULL,
    "SortOrder" INTEGER NOT NULL,
    "ParentId" TEXT NULL,
    CONSTRAINT "FK_Sectors_Sectors_ParentId" FOREIGN KEY ("ParentId") REFERENCES "Sectors" ("Id")
);
CREATE TABLE "Submissions" (
    "Id" TEXT NOT NULL CONSTRAINT "PK_Submissions" PRIMARY KEY,
    "Name" TEXT NOT NULL,
    "AgreeToTerms" INTEGER NOT NULL,
    "CreatedAt" TEXT NOT NULL,
    "UpdatedAt" TEXT NOT NULL
);
CREATE TABLE "SubmissionSectors" (
    "SubmissionId" TEXT NOT NULL,
    "SectorId" TEXT NOT NULL,
    CONSTRAINT "PK_SubmissionSectors" PRIMARY KEY ("SubmissionId", "SectorId"),
    CONSTRAINT "FK_SubmissionSectors_Sectors_SectorId" FOREIGN KEY ("SectorId") REFERENCES "Sectors" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SubmissionSectors_Submissions_SubmissionId" FOREIGN KEY ("SubmissionId") REFERENCES "Submissions" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Sectors_ParentId" ON "Sectors" ("ParentId");
CREATE INDEX "IX_SubmissionSectors_SectorId" ON "SubmissionSectors" ("SectorId");
COMMIT;
